        if 'minProperties' in schema and len(value)<schema['minProperties']: errs.append(f'{path}: must have at least {schema["minProperties"]} properties')
        if 'maxProperties' in schema and len(value)>schema['maxProperties']: errs.append(f'{path}: must have at most {schema["maxProperties"]} properties')
    if isinstance(value, list):
