        if 'exclusiveMinimum' in schema and value<=schema['exclusiveMinimum']: errs.append(f'{path}: must be > {schema["exclusiveMinimum"]}')
        if 'exclusiveMaximum' in schema and value>=schema['exclusiveMaximum']: errs.append(f'{path}: must be < {schema["exclusiveMaximum"]}')
