"""Project configuration and CFV environment option loading."""
import ast
import os
import re

try:
    import tomllib
except ImportError:  # Python 3.10
    tomllib = None


_TOP_TYPES = {
    "exclude-dirs": list, "exclude-file-types": list, "file-types": list,
    "depth": int, "reporter": list, "groupby": list, "quiet": bool,
    "require-schema": bool, "no-schema": bool, "schemastore": bool,
    "schemastore-path": str, "globbing": bool, "gitignore": bool,
}
_VALID = set(_TOP_TYPES) | {"schema-map", "type-map", "validators"}
_ENV = {
    "depth": "DEPTH", "exclude-dirs": "EXCLUDE_DIRS",
    "exclude-file-types": "EXCLUDE_FILE_TYPES", "file-types": "FILE_TYPES",
    "reporter": "REPORTER", "groupby": "GROUPBY", "quiet": "QUIET",
    "require-schema": "REQUIRE_SCHEMA", "no-schema": "NO_SCHEMA",
    "schemastore": "SCHEMASTORE", "schemastore-path": "SCHEMASTORE_PATH",
    "globbing": "GLOBBING", "gitignore": "GITIGNORE",
}


def _simple_toml(text):
    """Parse the ordinary scalar/array/table subset used by .cfv.toml."""
    result = {}
    current = result
    lines = iter(enumerate(text.splitlines(), 1))
    for n, raw in lines:
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        m = re.fullmatch(r"\[([^\]]+)\]", line)
        if m:
            current = result
            for part in m.group(1).split("."):
                part = part.strip().strip('"\'')
                current = current.setdefault(part, {})
            continue
        if "=" not in line:
            raise ValueError(f"line {n}: expected key = value")
        key, value = (x.strip() for x in line.split("=", 1))
        key = key.strip('"\'')
        # Remove trailing comments outside a quoted string.
        quote = None
        for i, c in enumerate(value):
            if quote:
                if c == quote and (i == 0 or value[i - 1] != "\\"):
                    quote = None
            elif c in "\"'":
                quote = c
            elif c == "#":
                value = value[:i].rstrip()
                break
        if value.startswith('"""') or value.startswith("'''"):
            # Basic multiline string support.
            marker = value[:3]
            if value.endswith(marker) and len(value) > 6:
                val = value[3:-3]
            else:
                chunks = [value[3:]]
                while not chunks[-1].endswith(marker):
                    try:
                        _, more = next(lines)
                    except StopIteration:
                        raise ValueError(f"line {n}: unterminated multiline string")
                    chunks.append(more)
                val = "\n".join(chunks)[:-3]
        else:
            try:
                val = ast.literal_eval(value)
            except Exception:
                if value.lower() in ("true", "false"):
                    val = value.lower() == "true"
                elif re.fullmatch(r"[+-]?\d+", value):
                    val = int(value)
                elif re.fullmatch(r"[+-]?\d+\.\d+", value):
                    val = float(value)
                else:
                    raise ValueError(f"line {n}: invalid value")
        current[key] = val
    return result


def _parse(text):
    if tomllib:
        return tomllib.loads(text)
    return _simple_toml(text)


def _discover(path=None):
    if path:
        return os.path.abspath(path)
    cur = os.path.abspath(os.getcwd())
    while True:
        candidate = os.path.join(cur, ".cfv.toml")
        if os.path.isfile(candidate):
            return candidate
        parent = os.path.dirname(cur)
        if parent == cur:
            return None
        cur = parent


def _validate(data, filename):
    if not isinstance(data, dict):
        return "schema validation failed: (root): Invalid type. Expected: object, given: string"
    unknown = set(data) - _VALID
    if unknown:
        key = sorted(unknown)[0]
        return f'schema validation failed: (root): Additional property {key} is not allowed'
    for key, expected in _TOP_TYPES.items():
        if key not in data:
            continue
        val = data[key]
        ok = isinstance(val, expected) and not (expected is int and isinstance(val, bool))
        if expected is list:
            ok = isinstance(val, list) and all(isinstance(x, str) for x in val)
        if not ok:
            return f"schema validation failed: {key}: Invalid type. Expected {expected.__name__}"
    for key in ("schema-map", "type-map"):
        if key in data and (not isinstance(data[key], dict) or not all(isinstance(k, str) and isinstance(v, str) for k, v in data[key].items())):
            return f"schema validation failed: {key}: Invalid type. Expected object"
    if "depth" in data and data["depth"] < 0:
        return "schema validation failed: depth: Must be greater than or equal to 0"
    if "validators" in data:
        validators = data["validators"]
        if not isinstance(validators, dict):
            return "schema validation failed: validators: Invalid type. Expected object"
        allowed = {
            "csv": {"delimiter": str, "comment": str, "lazy-quotes": bool},
            "json": {"forbid-duplicate-keys": bool},
            "ini": {"forbid-duplicate-keys": bool},
        }
        for typ, opts in validators.items():
            if typ not in allowed:
                return f"schema validation failed: validators: Additional property {typ} is not allowed"
            if not isinstance(opts, dict):
                return f"schema validation failed: validators.{typ}: Invalid type. Expected object"
            for opt, value in opts.items():
                if opt not in allowed[typ]:
                    return f"schema validation failed: validators.{typ}: Additional property {opt} is not allowed"
                expected = allowed[typ][opt]
                if not isinstance(value, expected):
                    return f"schema validation failed: validators.{typ}.{opt}: Invalid type. Expected {expected.__name__}"
    return None


def load_options(config_path=None, no_config=False):
    """Return (options, error); options combine file settings then CFV_* vars."""
    data = {}
    filename = None if no_config else _discover(config_path)
    if filename:
        try:
            with open(filename, encoding="utf-8") as f:
                data = _parse(f.read())
        except Exception as e:
            return {}, f"loading config file: reading config file: {e}"
        err = _validate(data, filename)
        if err:
            return {}, f"loading config file: config file {filename}: {err}"
    options = dict(data)
    for key, envkey in _ENV.items():
        env_name = "CFV_" + envkey
        if env_name not in os.environ:
            continue
        raw = os.environ[env_name]
        if key in ("depth",):
            try:
                options[key] = int(raw)
            except ValueError:
                return {}, f"parse error: invalid value {raw!r} for {env_name}"
        elif key in ("quiet", "require-schema", "no-schema", "schemastore", "globbing", "gitignore"):
            values = {"1": True, "t": True, "T": True, "true": True, "TRUE": True,
                      "True": True, "0": False, "f": False, "F": False, "false": False,
                      "FALSE": False, "False": False}
            if raw not in values:
                return {}, f"parse error: invalid value {raw!r} for {env_name}"
            options[key] = values[raw]
        else:
            options[key] = [x.strip() for x in raw.split(",") if x.strip()] if key in ("reporter", "groupby") else raw
    return options, None
